import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            a = []
            for _ in range(n):
                a.append(int(next(iterator)))
        except StopIteration:
            break

        if n == 1:
            results.append(str(a[0]))
        else:
            total_and = a[0]
            for x in a[1:]:
                total_and &= x
            results.append(str(total_and))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
